1	/**
2	 * Policy-as-Code v1 - Versioned, Testable, Signed Policies
3	 * 
4	 * This module manages policies as code:
5	 * - Version control for all policy changes
6	 * - Testable policy rules (unit tests for policies)
7	 * - Cryptographic signing for policy integrity
8	 * - Diff generation for policy changes
9	 * - Rollback capability
10	 * 
11	 * Policy Structure:
12	 * - Policies are YAML files in /policies directory
13	 * - Each policy has: version, rules, tests, signature
14	 * - Changes require: diff review, test pass, signature
15	 */
16	
17	import * as crypto from "crypto";
18	import * as yaml from "yaml";
19	import * as fs from "fs";
20	import * as path from "path";
21	import { governanceLog } from '../_core/logger';
22	
23	export interface PolicyRule {
24	  id: string;
25	  name: string;
26	  description: string;
27	  severity: "P0" | "P1" | "P2";
28	  condition: string;  // Expression to evaluate
29	  action: "block" | "warn" | "log";
30	  message: string;
31	  enabled: boolean;
32	}
33	
34	export interface PolicyTest {
35	  id: string;
36	  name: string;
37	  rule_id: string;
38	  input: object;
39	  expected_result: "pass" | "fail";
40	  expected_action?: "block" | "warn" | "log";
41	}
42	
43	export interface PolicyVersion {
44	  version: string;
45	  created_at: Date;
46	  created_by: string;
47	  description: string;
48	  rules: PolicyRule[];
49	  tests: PolicyTest[];
50	  signature: string;
51	  parent_version?: string;
52	}
53	
54	export interface PolicyDiff {
55	  from_version: string;
56	  to_version: string;
57	  rules_added: PolicyRule[];
58	  rules_removed: PolicyRule[];
59	  rules_modified: { rule_id: string; changes: string[] }[];
60	  tests_added: PolicyTest[];
61	  tests_removed: PolicyTest[];
62	}
63	
64	export interface PolicyTestResult {
65	  test_id: string;
66	  test_name: string;
67	  rule_id: string;
68	  passed: boolean;
69	  expected: string;
70	  actual: string;
71	  error?: string;
72	}
73	
74	// In-memory policy store (in production, would be git-backed)
75	const policyVersions: Map<string, PolicyVersion> = new Map();
76	let currentVersion: string | null = null;
77	
78	/**
79	 * Generate cryptographic signature for policy
80	 */
81	function signPolicy(policy: Omit<PolicyVersion, "signature">): string {
82	  const content = JSON.stringify({
83	    version: policy.version,
84	    rules: policy.rules,
85	    tests: policy.tests,
86	    created_by: policy.created_by,
87	  });
88	  
89	  return crypto
90	    .createHash("sha256")
91	    .update(content)
92	    .digest("hex")
93	    .substring(0, 16);
94	}
95	
96	/**
97	 * Verify policy signature
98	 */
99	export function verifyPolicySignature(policy: PolicyVersion): boolean {
100	  const expectedSignature = signPolicy({
101	    version: policy.version,
102	    created_at: policy.created_at,
103	    created_by: policy.created_by,
104	    description: policy.description,
105	    rules: policy.rules,
106	    tests: policy.tests,
107	    parent_version: policy.parent_version,
108	  });
109	  
110	  return policy.signature === expectedSignature;
111	}
112	
113	/**
114	 * Create a new policy version
115	 */
116	export function createPolicyVersion(
117	  version: string,
118	  createdBy: string,
119	  description: string,
120	  rules: PolicyRule[],
121	  tests: PolicyTest[],
122	  parentVersion?: string
123	): PolicyVersion {
124	  const policy: Omit<PolicyVersion, "signature"> = {
125	    version,
126	    created_at: new Date(),
127	    created_by: createdBy,
128	    description,
129	    rules,
130	    tests,
131	    parent_version: parentVersion,
132	  };
133	  
134	  const signature = signPolicy(policy);
135	  
136	  const fullPolicy: PolicyVersion = {
137	    ...policy,
138	    signature,
139	  };
140	  
141	  policyVersions.set(version, fullPolicy);
142	  currentVersion = version;
143	  
144	  return fullPolicy;
145	}
146	
147	/**
148	 * Load policy from YAML file
149	 */
150	export function loadPolicyFromFile(filePath: string): PolicyVersion | null {
151	  try {
152	    const content = fs.readFileSync(filePath, "utf-8");
153	    const parsed = yaml.parse(content);
154	    
155	    const rules: PolicyRule[] = [];
156	    const tests: PolicyTest[] = [];
157	    
158	    // Extract rules from various sections
159	    if (parsed.gate_rules) {
160	      for (const rule of parsed.gate_rules.release_gate || []) {
161	        rules.push({
162	          id: rule.rule,
163	          name: rule.rule,
164	          description: rule.condition,
165	          severity: "P0",
166	          condition: rule.condition,
167	          action: rule.action === "block_if_false" ? "block" : "warn",
168	          message: `Gate rule failed: ${rule.rule}`,
169	          enabled: true,
170	        });
171	      }
172	    }
173	    
174	    // Extract violation codes as rules
175	    if (parsed.violation_codes) {
176	      for (const [severity, violations] of Object.entries(parsed.violation_codes)) {
177	        for (const v of violations as unknown[]) {
178	          rules.push({
179	            id: v.code,
180	            name: v.code,
181	            description: v.description,
182	            severity: severity.startsWith("P0") ? "P0" : severity.startsWith("P1") ? "P1" : "P2",
183	            condition: `violation_code == "${v.code}"`,
184	            action: v.action === "block_release" ? "block" : v.action === "warn_and_require_fix" ? "warn" : "log",
185	            message: v.description,
186	            enabled: true,
187	          });
188	        }
189	      }
190	    }
191	    
192	    // Extract forbidden terms as rules
193	    if (parsed.forbidden) {
194	      for (const headline of parsed.forbidden.headlines || []) {
195	        rules.push({
196	          id: `FORBIDDEN_HEADLINE_${headline.pattern.replace(/\s+/g, "_").toUpperCase()}`,
197	          name: `Forbidden Headline: ${headline.pattern}`,
198	          description: headline.reason,
199	          severity: "P0",
200	          condition: `headline.toLowerCase().includes("${headline.pattern.toLowerCase()}")`,
201	          action: "block",
202	          message: `Forbidden headline pattern: ${headline.pattern}`,
203	          enabled: true,
204	        });
205	      }
206	    }
207	    
208	    const version = parsed.version || "1.0.0";
209	    
210	    return createPolicyVersion(
211	      version,
212	      parsed.approved_by?.[0]?.user || "system",
213	      `Loaded from ${filePath}`,
214	      rules,
215	      tests,
216	      undefined
217	    );
218	  } catch (error) {
219	    governanceLog.error("Failed to load policy:", error);
220	    return null;
221	  }
222	}
223	
224	/**
225	 * Generate diff between two policy versions
226	 */
227	export function generatePolicyDiff(
228	  fromVersion: string,
229	  toVersion: string
230	): PolicyDiff | null {
231	  const from = policyVersions.get(fromVersion);
232	  const to = policyVersions.get(toVersion);
233	  
234	  if (!from || !to) return null;
235	  
236	  const fromRuleIds = new Set(from.rules.map(r => r.id));
237	  const toRuleIds = new Set(to.rules.map(r => r.id));
238	  
239	  const rulesAdded = to.rules.filter(r => !fromRuleIds.has(r.id));
240	  const rulesRemoved = from.rules.filter(r => !toRuleIds.has(r.id));
241	  
242	  const rulesModified: { rule_id: string; changes: string[] }[] = [];
243	  for (const toRule of to.rules) {
244	    if (fromRuleIds.has(toRule.id)) {
245	      const fromRule = from.rules.find(r => r.id === toRule.id)!;
246	      const changes: string[] = [];
247	      
248	      if (fromRule.severity !== toRule.severity) {
249	        changes.push(`severity: ${fromRule.severity} → ${toRule.severity}`);
250	      }
251	      if (fromRule.action !== toRule.action) {
252	        changes.push(`action: ${fromRule.action} → ${toRule.action}`);
253	      }
254	      if (fromRule.enabled !== toRule.enabled) {
255	        changes.push(`enabled: ${fromRule.enabled} → ${toRule.enabled}`);
256	      }
257	      if (fromRule.condition !== toRule.condition) {
258	        changes.push(`condition changed`);
259	      }
260	      
261	      if (changes.length > 0) {
262	        rulesModified.push({ rule_id: toRule.id, changes });
263	      }
264	    }
265	  }
266	  
267	  const fromTestIds = new Set(from.tests.map(t => t.id));
268	  const toTestIds = new Set(to.tests.map(t => t.id));
269	  
270	  const testsAdded = to.tests.filter(t => !fromTestIds.has(t.id));
271	  const testsRemoved = from.tests.filter(t => !toTestIds.has(t.id));
272	  
273	  return {
274	    from_version: fromVersion,
275	    to_version: toVersion,
276	    rules_added: rulesAdded,
277	    rules_removed: rulesRemoved,
278	    rules_modified: rulesModified,
279	    tests_added: testsAdded,
280	    tests_removed: testsRemoved,
281	  };
282	}
283	
284	/**
285	 * Run policy tests
286	 */
287	export function runPolicyTests(version?: string): PolicyTestResult[] {
288	  const policy = version 
289	    ? policyVersions.get(version) 
290	    : currentVersion 
291	      ? policyVersions.get(currentVersion) 
292	      : null;
293	  
294	  if (!policy) return [];
295	  
296	  const results: PolicyTestResult[] = [];
297	  
298	  for (const test of policy.tests) {
299	    const rule = policy.rules.find(r => r.id === test.rule_id);
300	    
301	    if (!rule) {
302	      results.push({
303	        test_id: test.id,
304	        test_name: test.name,
305	        rule_id: test.rule_id,
306	        passed: false,
307	        expected: test.expected_result,
308	        actual: "error",
309	        error: `Rule ${test.rule_id} not found`,
310	      });
311	      continue;
312	    }
313	    
314	    try {
315	      // Simple condition evaluation (in production, would use a proper expression evaluator)
316	      // For now, just check if the test expects the rule to be enabled
317	      const ruleWouldFire = rule.enabled;
318	      const testExpectsBlock = test.expected_result === "fail";
319	      
320	      const passed = (ruleWouldFire && testExpectsBlock) || (!ruleWouldFire && !testExpectsBlock);
321	      
322	      results.push({
323	        test_id: test.id,
324	        test_name: test.name,
325	        rule_id: test.rule_id,
326	        passed,
327	        expected: test.expected_result,
328	        actual: ruleWouldFire ? "fail" : "pass",
329	      });
330	    } catch (error: unknown) {
331	      results.push({
332	        test_id: test.id,
333	        test_name: test.name,
334	        rule_id: test.rule_id,
335	        passed: false,
336	        expected: test.expected_result,
337	        actual: "error",
338	        error: error.message,
339	      });
340	    }
341	  }
342	  
343	  return results;
344	}
345	
346	/**
347	 * Rollback to a previous policy version
348	 */
349	export function rollbackPolicy(toVersion: string): boolean {
350	  if (!policyVersions.has(toVersion)) return false;
351	  currentVersion = toVersion;
352	  return true;
353	}
354	
355	/**
356	 * Get current policy
357	 */
358	export function getCurrentPolicy(): PolicyVersion | null {
359	  return currentVersion ? policyVersions.get(currentVersion) || null : null;
360	}
361	
362	/**
363	 * Get all policy versions
364	 */
365	export function getAllPolicyVersions(): PolicyVersion[] {
366	  return Array.from(policyVersions.values());
367	}
368	
369	/**
370	 * Evaluate a rule against input
371	 */
372	export function evaluateRule(
373	  rule: PolicyRule,
374	  input: Record<string, unknown>
375	): { triggered: boolean; action: string; message: string } {
376	  if (!rule.enabled) {
377	    return { triggered: false, action: "none", message: "" };
378	  }
379	  
380	  // Simple pattern matching for common conditions
381	  // In production, would use a proper expression evaluator
382	  let triggered = false;
383	  
384	  if (rule.condition.includes("violation_code")) {
385	    const codeMatch = rule.condition.match(/violation_code == "([^"]+)"/);
386	    if (codeMatch && input.violation_codes?.includes(codeMatch[1])) {
387	      triggered = true;
388	    }
389	  }
390	  
391	  if (rule.condition.includes("headline")) {
392	    const patternMatch = rule.condition.match(/includes\("([^"]+)"\)/);
393	    if (patternMatch && input.headline?.toLowerCase().includes(patternMatch[1].toLowerCase())) {
394	      triggered = true;
395	    }
396	  }
397	  
398	  if (rule.condition.includes("score")) {
399	    const scoreMatch = rule.condition.match(/score\s*([<>=]+)\s*(\d+)/);
400	    if (scoreMatch && input.score !== undefined) {
401	      const op = scoreMatch[1];
402	      const threshold = parseInt(scoreMatch[2]);
403	      if (op === "<" && input.score < threshold) triggered = true;
404	      if (op === "<=" && input.score <= threshold) triggered = true;
405	      if (op === ">" && input.score > threshold) triggered = true;
406	      if (op === ">=" && input.score >= threshold) triggered = true;
407	    }
408	  }
409	  
410	  return {
411	    triggered,
412	    action: triggered ? rule.action : "none",
413	    message: triggered ? rule.message : "",
414	  };
415	}
416	
417	/**
418	 * Evaluate all rules against input
419	 */
420	export function evaluateAllRules(
421	  input: Record<string, unknown>,
422	  version?: string
423	): {
424	  should_block: boolean;
425	  triggered_rules: { rule_id: string; severity: string; action: string; message: string }[];
426	  policy_version: string;
427	  policy_signature: string;
428	} {
429	  const policy = version 
430	    ? policyVersions.get(version) 
431	    : currentVersion 
432	      ? policyVersions.get(currentVersion) 
433	      : null;
434	  
435	  if (!policy) {
436	    return {
437	      should_block: false,
438	      triggered_rules: [],
439	      policy_version: "none",
440	      policy_signature: "none",
441	    };
442	  }
443	  
444	  const triggeredRules: { rule_id: string; severity: string; action: string; message: string }[] = [];
445	  let shouldBlock = false;
446	  
447	  for (const rule of policy.rules) {
448	    const result = evaluateRule(rule, input);
449	    if (result.triggered) {
450	      triggeredRules.push({
451	        rule_id: rule.id,
452	        severity: rule.severity,
453	        action: result.action,
454	        message: result.message,
455	      });
456	      
457	      if (result.action === "block") {
458	        shouldBlock = true;
459	      }
460	    }
461	  }
462	  
463	  return {
464	    should_block: shouldBlock,
465	    triggered_rules: triggeredRules,
466	    policy_version: policy.version,
467	    policy_signature: policy.signature,
468	  };
469	}
470	
471	/**
472	 * Generate policy proof block
473	 */
474	export function generatePolicyProofBlock(
475	  evaluationResult: ReturnType<typeof evaluateAllRules>,
476	  input: Record<string, unknown>
477	): object {
478	  return {
479	    proof_type: "policy_evaluation",
480	    policy_version: evaluationResult.policy_version,
481	    policy_signature: evaluationResult.policy_signature,
482	    input_hash: crypto.createHash("sha256").update(JSON.stringify(input)).digest("hex").substring(0, 16),
483	    should_block: evaluationResult.should_block,
484	    triggered_rules_count: evaluationResult.triggered_rules.length,
485	    triggered_rules: evaluationResult.triggered_rules,
486	    timestamp: new Date().toISOString(),
487	  };
488	}
489	
490	export const PolicyAsCode = {
491	  createPolicyVersion,
492	  loadPolicyFromFile,
493	  verifyPolicySignature,
494	  generatePolicyDiff,
495	  runPolicyTests,
496	  rollbackPolicy,
497	  getCurrentPolicy,
498	  getAllPolicyVersions,
499	  evaluateRule,
500	  evaluateAllRules,
501	  generatePolicyProofBlock,
502	};
