/**
 * Policy-as-Code v1 - Versioned, Testable, Signed Policies
 * 
 * This module manages policies as code:
 * - Version control for all policy changes
 * - Testable policy rules (unit tests for policies)
 * - Cryptographic signing for policy integrity
 * - Diff generation for policy changes
 * - Rollback capability
 * 
 * Policy Structure:
 * - Policies are YAML files in /policies directory
 * - Each policy has: version, rules, tests, signature
 * - Changes require: diff review, test pass, signature
 */

import * as crypto from "crypto";
import * as yaml from "yaml";
import * as fs from "fs";
import * as path from "path";
import { governanceLog } from '../_core/logger';

export interface PolicyRule {
  id: string;
  name: string;
  description: string;
  severity: "P0" | "P1" | "P2";
  condition: string;  // Expression to evaluate
  action: "block" | "warn" | "log";
  message: string;
  enabled: boolean;
}

export interface PolicyTest {
  id: string;
  name: string;
  rule_id: string;
  input: object;
  expected_result: "pass" | "fail";
  expected_action?: "block" | "warn" | "log";
}

export interface PolicyVersion {
  version: string;
  created_at: Date;
  created_by: string;
  description: string;
  rules: PolicyRule[];
  tests: PolicyTest[];
  signature: string;
  parent_version?: string;
}

export interface PolicyDiff {
  from_version: string;
  to_version: string;
  rules_added: PolicyRule[];
  rules_removed: PolicyRule[];
  rules_modified: { rule_id: string; changes: string[] }[];
  tests_added: PolicyTest[];
  tests_removed: PolicyTest[];
}

export interface PolicyTestResult {
  test_id: string;
  test_name: string;
  rule_id: string;
  passed: boolean;
  expected: string;
  actual: string;
  error?: string;
}

// In-memory policy store (in production, would be git-backed)
const policyVersions: Map<string, PolicyVersion> = new Map();
let currentVersion: string | null = null;

/**
 * Generate cryptographic signature for policy
 */
function signPolicy(policy: Omit<PolicyVersion, "signature">): string {
  const content = JSON.stringify({
    version: policy.version,
    rules: policy.rules,
    tests: policy.tests,
    created_by: policy.created_by,
  });

  return crypto
    .createHash("sha256")
    .update(content)
    .digest("hex")
    .substring(0, 16);
}

/**
 * Verify policy signature
 */
export function verifyPolicySignature(policy: PolicyVersion): boolean {
  const expectedSignature = signPolicy({
    version: policy.version,
    created_at: policy.created_at,
    created_by: policy.created_by,
    description: policy.description,
    rules: policy.rules,
    tests: policy.tests,
    parent_version: policy.parent_version,
  });

  return policy.signature === expectedSignature;
}

/**
 * Create a new policy version
 */
export function createPolicyVersion(
  version: string,
  createdBy: string,
  description: string,
  rules: PolicyRule[],
  tests: PolicyTest[],
  parentVersion?: string
): PolicyVersion {
  const policy: Omit<PolicyVersion, "signature"> = {
    version,
    created_at: new Date(),
    created_by: createdBy,
    description,
    rules,
    tests,
    parent_version: parentVersion,
  };

  const signature = signPolicy(policy);

  const fullPolicy: PolicyVersion = {
    ...policy,
    signature,
  };

  policyVersions.set(version, fullPolicy);
  currentVersion = version;

  return fullPolicy;
}

/**
 * Load policy from YAML file
 */
export function loadPolicyFromFile(filePath: string): PolicyVersion | null {
  try {
    const content = fs.readFileSync(filePath, "utf-8");
    const parsed = yaml.parse(content);

    const rules: PolicyRule[] = [];
    const tests: PolicyTest[] = [];

    // Extract rules from various sections
    if (parsed.gate_rules) {
      for (const rule of parsed.gate_rules.release_gate || []) {
        rules.push({
          id: rule.rule,
          name: rule.rule,
          description: rule.condition,
          severity: "P0",
          condition: rule.condition,
          action: rule.action === "block_if_false" ? "block" : "warn",
          message: `Gate rule failed: ${rule.rule}`,
          enabled: true,
        });
      }
    }

    // Extract violation codes as rules
    if (parsed.violation_codes) {
      for (const [severity, violations] of Object.entries(parsed.violation_codes)) {
        for (const v of violations as unknown[]) {
          rules.push({
            id: v.code,
            name: v.code,
            description: v.description,
            severity: severity.startsWith("P0") ? "P0" : severity.startsWith("P1") ? "P1" : "P2",
            condition: `violation_code == "${v.code}"`,
            action: v.action === "block_release" ? "block" : v.action === "warn_and_require_fix" ? "warn" : "log",
            message: v.description,
            enabled: true,
          });
        }
      }
    }

    // Extract forbidden terms as rules
    if (parsed.forbidden) {
      for (const headline of parsed.forbidden.headlines || []) {
        rules.push({
          id: `FORBIDDEN_HEADLINE_${headline.pattern.replace(/\s+/g, "_").toUpperCase()}`,
          name: `Forbidden Headline: ${headline.pattern}`,
          description: headline.reason,
          severity: "P0",
          condition: `headline.toLowerCase().includes("${headline.pattern.toLowerCase()}")`,
          action: "block",
          message: `Forbidden headline pattern: ${headline.pattern}`,
          enabled: true,
        });
      }
    }

    const version = parsed.version || "1.0.0";

    return createPolicyVersion(
      version,
      parsed.approved_by?.[0]?.user || "system",
      `Loaded from ${filePath}`,
      rules,
      tests,
      undefined
    );
  } catch (error) {
    governanceLog.error("Failed to load policy:", error);
    return null;
  }
}

/**
 * Generate diff between two policy versions
 */
export function generatePolicyDiff(
  fromVersion: string,
  toVersion: string
): PolicyDiff | null {
  const from = policyVersions.get(fromVersion);
  const to = policyVersions.get(toVersion);

  if (!from || !to) return null;

  const fromRuleIds = new Set(from.rules.map(r => r.id));
  const toRuleIds = new Set(to.rules.map(r => r.id));

  const rulesAdded = to.rules.filter(r => !fromRuleIds.has(r.id));
  const rulesRemoved = from.rules.filter(r => !toRuleIds.has(r.id));

  const rulesModified: { rule_id: string; changes: string[] }[] = [];
  for (const toRule of to.rules) {
    if (fromRuleIds.has(toRule.id)) {
      const fromRule = from.rules.find(r => r.id === toRule.id)!;
      const changes: string[] = [];

      if (fromRule.severity !== toRule.severity) {
        changes.push(`severity: ${fromRule.severity} → ${toRule.severity}`);
      }
      if (fromRule.action !== toRule.action) {
        changes.push(`action: ${fromRule.action} → ${toRule.action}`);
      }
      if (fromRule.enabled !== toRule.enabled) {
        changes.push(`enabled: ${fromRule.enabled} → ${toRule.enabled}`);
      }
      if (fromRule.condition !== toRule.condition) {
        changes.push(`condition changed`);
      }

      if (changes.length > 0) {
        rulesModified.push({ rule_id: toRule.id, changes });
      }
    }
  }

  const fromTestIds = new Set(from.tests.map(t => t.id));
  const toTestIds = new Set(to.tests.map(t => t.id));

  const testsAdded = to.tests.filter(t => !fromTestIds.has(t.id));
  const testsRemoved = from.tests.filter(t => !toTestIds.has(t.id));

  return {
    from_version: fromVersion,
    to_version: toVersion,
    rules_added: rulesAdded,
    rules_removed: rulesRemoved,
    rules_modified: rulesModified,
    tests_added: testsAdded,
    tests_removed: testsRemoved,
  };
}

/**
 * Run policy tests
 */
export function runPolicyTests(version?: string): PolicyTestResult[] {
  const policy = version 
    ? policyVersions.get(version) 
    : currentVersion 
      ? policyVersions.get(currentVersion) 
      : null;

  if (!policy) return [];

  const results: PolicyTestResult[] = [];

  for (const test of policy.tests) {
    const rule = policy.rules.find(r => r.id === test.rule_id);

    if (!rule) {
      results.push({
        test_id: test.id,
        test_name: test.name,
        rule_id: test.rule_id,
        passed: false,
        expected: test.expected_result,
        actual: "error",
        error: `Rule ${test.rule_id} not found`,
      });
      continue;
    }

    try {
      // Simple condition evaluation (in production, would use a proper expression evaluator)
      // For now, just check if the test expects the rule to be enabled
      const ruleWouldFire = rule.enabled;
      const testExpectsBlock = test.expected_result === "fail";

      const passed = (ruleWouldFire && testExpectsBlock) || (!ruleWouldFire && !testExpectsBlock);

      results.push({
        test_id: test.id,
        test_name: test.name,
        rule_id: test.rule_id,
        passed,
        expected: test.expected_result,
        actual: ruleWouldFire ? "fail" : "pass",
      });
    } catch (error: unknown) {
      results.push({
        test_id: test.id,
        test_name: test.name,
        rule_id: test.rule_id,
        passed: false,
        expected: test.expected_result,
        actual: "error",
        error: error.message,
      });
    }
  }

  return results;
}

/**
 * Rollback to a previous policy version
 */
export function rollbackPolicy(toVersion: string): boolean {
  if (!policyVersions.has(toVersion)) return false;
  currentVersion = toVersion;
  return true;
}

/**
 * Get current policy
 */
export function getCurrentPolicy(): PolicyVersion | null {
  return currentVersion ? policyVersions.get(currentVersion) || null : null;
}

/**
 * Get all policy versions
 */
export function getAllPolicyVersions(): PolicyVersion[] {
  return Array.from(policyVersions.values());
}

/**
 * Evaluate a rule against input
 */
export function evaluateRule(
  rule: PolicyRule,
  input: Record<string, unknown>
): { triggered: boolean; action: string; message: string } {
  if (!rule.enabled) {
    return { triggered: false, action: "none", message: "" };
  }

  // Simple pattern matching for common conditions
  // In production, would use a proper expression evaluator
  let triggered = false;

  if (rule.condition.includes("violation_code")) {
    const codeMatch = rule.condition.match(/violation_code == "([^"]+)"/);
    if (codeMatch && input.violation_codes?.includes(codeMatch[1])) {
      triggered = true;
    }
  }

  if (rule.condition.includes("headline")) {
    const patternMatch = rule.condition.match(/includes\("([^"]+)"\)/);
    if (patternMatch && input.headline?.toLowerCase().includes(patternMatch[1].toLowerCase())) {
      triggered = true;
    }
  }

  if (rule.condition.includes("score")) {
    const scoreMatch = rule.condition.match(/score\s*([<>=]+)\s*(\d+)/);
    if (scoreMatch && input.score !== undefined) {
      const op = scoreMatch[1];
      const threshold = parseInt(scoreMatch[2]);
      if (op === "<" && input.score < threshold) triggered = true;
      if (op === "<=" && input.score <= threshold) triggered = true;
      if (op === ">" && input.score > threshold) triggered = true;
      if (op === ">=" && input.score >= threshold) triggered = true;
    }
  }

  return {
    triggered,
    action: triggered ? rule.action : "none",
    message: triggered ? rule.message : "",
  };
}

/**
 * Evaluate all rules against input
 */
export function evaluateAllRules(
  input: Record<string, unknown>,
  version?: string
): {
  should_block: boolean;
  triggered_rules: { rule_id: string; severity: string; action: string; message: string }[];
  policy_version: string;
  policy_signature: string;
} {
  const policy = version 
    ? policyVersions.get(version) 
    : currentVersion 
      ? policyVersions.get(currentVersion) 
      : null;

  if (!policy) {
    return {
      should_block: false,
      triggered_rules: [],
      policy_version: "none",
      policy_signature: "none",
    };
  }

  const triggeredRules: { rule_id: string; severity: string; action: string; message: string }[] = [];
  let shouldBlock = false;

  for (const rule of policy.rules) {
    const result = evaluateRule(rule, input);
    if (result.triggered) {
      triggeredRules.push({
        rule_id: rule.id,
        severity: rule.severity,
        action: result.action,
        message: result.message,
      });

      if (result.action === "block") {
        shouldBlock = true;
      }
    }
  }

  return {
    should_block: shouldBlock,
    triggered_rules: triggeredRules,
    policy_version: policy.version,
    policy_signature: policy.signature,
  };
}

/**
 * Generate policy proof block
 */
export function generatePolicyProofBlock(
  evaluationResult: ReturnType<typeof evaluateAllRules>,
  input: Record<string, unknown>
): object {
  return {
    proof_type: "policy_evaluation",
    policy_version: evaluationResult.policy_version,
    policy_signature: evaluationResult.policy_signature,
    input_hash: crypto.createHash("sha256").update(JSON.stringify(input)).digest("hex").substring(0, 16),
    should_block: evaluationResult.should_block,
    triggered_rules_count: evaluationResult.triggered_rules.length,
    triggered_rules: evaluationResult.triggered_rules,
    timestamp: new Date().toISOString(),
  };
}

export const PolicyAsCode = {
  createPolicyVersion,
  loadPolicyFromFile,
  verifyPolicySignature,
  generatePolicyDiff,
  runPolicyTests,
  rollbackPolicy,
  getCurrentPolicy,
  getAllPolicyVersions,
  evaluateRule,
  evaluateAllRules,
  generatePolicyProofBlock,
};

